let chanView: { page: number; list?: import('./alert').SlackChannel[]; def: string; note: string } | undefined
const CHAN_ROWS = 14

async function chanLoad($: any, python: string, repo: string): Promise<void> {
  try {
    const r = await $.process.run(channelsArgv(python, repo), { cwd: repo, timeoutMs: 30000 })
    const d = parseChannels(String(r.stdout ?? ''))
    chanView = { page: chanView?.page ?? 0, list: d.channels, def: d.default, note: d.error ? `一覧を読めなかった（${d.error.slice(0, 60)}）` : '' }
  } catch (err) {
    chanView = { page: 0, list: [], def: 'mention', note: `一覧を読めなかった（${String(err).slice(0, 60)}）` }
  }
  $.ui.invalidate('ui.render')
}

async function chanSet($: any, python: string, repo: string, id: string, watch: string): Promise<void> {
  try {
    const r = await $.process.run(setWatchArgv(python, repo, id, watch), { cwd: repo, timeoutMs: 30000 })
    if (r.exitCode === 0 && chanView?.list) {
      chanView.list = chanView.list.map(c => (c.id === id ? { ...c, watch, effective: watch } : c))
      chanView.note = ''
    } else if (chanView) chanView.note = `書き換えられなかった（exit ${r.exitCode}）`
  } catch (err) {
    if (chanView) chanView.note = `書き換えられなかった（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}
const SLACK_MSGS = 3 // newest messages under each

async function fetchSlack($: any, python: string, repo: string): Promise<void> {
  if (!python || !repo || slackBusy) return
  slackBusy = true
  try {
    const r = await $.process.run([python, `${repo}/scripts/slack/slack_feed.py`], { cwd: repo, timeoutMs: 240000 })
    const feed = parseSlack(String(r.stdout ?? ''))
    if (feed.error) { slackNoteSeq++; slackNote = `Slack を取れなかった（${feed.error.slice(0, 80)}）`; return }
    slackFeed = feed
    // A fetch clears only its own earlier failure, not what an action said (済みにした …).
    if (feed.errors.length) { slackNoteSeq++; slackNote = `取れなかった workspace・チャンネルあり: ${feed.errors.length}（${feed.errors[0].slice(0, 50)}）` }
    else if (/取れなかった/.test(slackNote)) { slackNoteSeq++; slackNote = '' }
  } catch (err) {
    slackNoteSeq++; slackNote = `Slack を取れなかった（${String(err).slice(0, 60)}）`
  } finally {
    slackBusy = false
    $.ui.invalidate('ui.render')
  }
}

export function slackCount(): number | undefined {
  if (!slackFeed) return undefined
  return slackFeed.items.filter(x => !slackDone.has(x.id)).length
}

async function slackMarkDone($: any, python: string, repo: string, ids: string[]): Promise<void> {
  if (ids.length === 0) return
  try {
    const r = await $.process.run(slackDoneArgv(python, repo, ids), { cwd: repo, timeoutMs: 30000 })
    if (r.exitCode === 0) {
      for (const id of ids) slackDone.add(id)
      slackSel = new Set(); slackMsgSel = new Set()
      slackNoteSeq++; slackNote = `済みにした: ${ids.length} 件（手元の記録だけ。Slack の未読はそのまま）`
    } else {
      slackNoteSeq++; slackNote = `済みにできなかった（exit ${r.exitCode}）`
    }
  } catch (err) {
    slackNoteSeq++; slackNote = `済みにできなかった（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}

// workspace → Slack MCP server name, from pluginConfigs (machine-specific, not in this repo).
