// ---- notes pane: a project's note → its contents → a number's pictures ----

const NOTES = 'notes'
type NotePj = { slug: string; title: string; code: string; data: string }
let notePjs: NotePj[] = []
let notesView:
  | { kind: 'list' }
  | { kind: 'toc'; pj: NotePj; rows: TocRow[] }
  | { kind: 'pngs'; pj: NotePj; rows: TocRow[]; row: TocRow; files: string[]; deep?: boolean; body?: string[]; full?: boolean }
  | { kind: 'image'; pj: NotePj; rows: TocRow[]; row: TocRow; files: string[]; file: string; src?: string; w?: number; h?: number; body?: string[] } = { kind: 'list' }
const BODY_LINES = 20
let notesNote = ''
const THUMB = '/tmp/ops-dash-notes-view.png'
const MAX_B64 = 2700000 // Image takes at most 2 MiB of picture

// The list comes from the hubs alone (nas_code and nas_data): nothing is read
// from the NAS until a project is chosen.
async function notesLoad($: any, repo: string): Promise<void> {
  if (hubs.length === 0) await loadHubs($, repo)
  const out: NotePj[] = []
  for (const h of hubs) {
    const code = frontValue(h.text, 'nas_code')
    const data = frontValue(h.text, 'nas_data')
    if (code && data) out.push({ slug: h.slug, title: h.title, code, data })
  }
  notePjs = out
}

// Only the head of note.md, up to the end of its contents (a note can be
// 10,000+ lines on a slow NAS): awk stops reading there.
async function notesOpenToc($: any, pj: NotePj): Promise<void> {
  notesView = { kind: 'toc', pj, rows: [] }
  notesNote = `${pj.code}/note/note.md の目次を読んでいます…`
  $.ui.invalidate('ui.render')
  try {
    const r = await $.process.run(['awk', '{ print } /<!-- TOC:END -->/ { exit }', `${pj.code}/note/note.md`], { timeoutMs: 20000 })
    const rows = tocRows(String(r.stdout ?? ''))
    notesView = { kind: 'toc', pj, rows }
    notesNote = rows.length > 0 ? '' : r.exitCode === 0 ? 'この note には目次がありません（scripts/note_toc.py で作る）' : `note を読めない（exit ${r.exitCode}）`
  } catch (err) {
    notesNote = `note を読めない（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}

// First the quick look: <number>/out/*.png only, no walking
// down the tree (the NAS is slow to walk). `deep` walks it, on request.
// The entry itself, read alongside: awk prints from the number's heading to
// the next "## " heading and stops there, not reading the rest of the note.
async function notesReadEntry($: any, pj: NotePj, id: string): Promise<string[]> {
  try {
    const prog = '$0 ~ "^## " id " — " { p = 1 } p && /^## / && $0 !~ "^## " id " — " { exit } p { print }'
    const r = await $.process.run(['awk', '-v', `id=${id}`, prog, `${pj.code}/note/note.md`], { timeoutMs: 20000 })
    return entryLines(String(r.stdout ?? ''), id)
  } catch {
    return []
  }
}

async function notesOpenPngs($: any, pj: NotePj, rows: TocRow[], row: TocRow, deep = false, body?: string[]): Promise<void> {
  const dir = `${pj.data}/${row.id}`
  notesView = { kind: 'pngs', pj, rows, row, files: [], deep, body }
  const bodyRead = body ? Promise.resolve(body) : notesReadEntry($, pj, row.id)
  notesNote = deep ? `${dir} の下の階層も探しています…` : `${dir}/out を見ています…`
  $.ui.invalidate('ui.render')
  try {
    const argv = deep
      ? ['find', dir, '-maxdepth', '6', '-type', 'f', '-iname', '*.png']
      : ['/bin/sh', '-c', 'for f in "$1"/out/*.png "$1"/out/*.PNG; do [ -f "$f" ] && echo "$f"; done; exit 0', 'sh', dir]
    const [r, lines] = await Promise.all([$.process.run(argv, { timeoutMs: deep ? 60000 : 15000 }), bodyRead])
    const files = pngList(String(r.stdout ?? ''), dir)
    notesView = { kind: 'pngs', pj, rows, row, files, deep, body: lines }
    const where = deep ? '下の階層まで探して' : 'out/ に'
    notesNote = files.length === 0 ? (r.exitCode === 0 ? `${where} png はありません` : `探せなかった（exit ${r.exitCode}）`) : `${where} ${files.length} 件${files.length >= 200 ? '（先頭 200 件）' : ''}`
  } catch (err) {
    notesNote = `探せなかった（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}

async function notesOpenImage($: any, v: { pj: NotePj; rows: TocRow[]; row: TocRow; files: string[] }, file: string): Promise<void> {
  const path = `${v.pj.data}/${v.row.id}/${file}`
  notesView = { ...v, kind: 'image', file }
  notesNote = '読み込んでいます…'
  $.ui.invalidate('ui.render')
  try {
    const dims = await $.process.run(['sips', '-g', 'pixelWidth', '-g', 'pixelHeight', path], { timeoutMs: 20000 })
    const w = Number(String(dims.stdout).match(/pixelWidth:\s*(\d+)/)?.[1] ?? 0)
    const h = Number(String(dims.stdout).match(/pixelHeight:\s*(\d+)/)?.[1] ?? 0)
    let src = bytesToBase64(await $.fs.read(path, { as: 'bytes' }))
    if (src.length > MAX_B64) {
      await $.process.run(['sips', '-Z', '1600', path, '--out', THUMB], { timeoutMs: 30000 })
      src = bytesToBase64(await $.fs.read(THUMB, { as: 'bytes' }))
    }
    if (!isBase64(src) || src.length > MAX_B64) {
      notesNote = '画像を読めなかった（大きすぎるか、png でない）'
      notesView = { ...v, kind: 'image', file }
    } else {
      notesView = { ...v, kind: 'image', file, src, w, h }
      notesNote = w && h ? `${w} × ${h} px` : ''
    }
  } catch (err) {
    notesNote = `画像を読めなかった（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}

// ---- fig pane: a draft figure any session drops in a folder, and the palette ----

// Any session puts a PNG in ~/.local/share/life/preview/ (figstyle.preview does
// it in one line); /fig shows the newest at once, the rest as a list, and the
// shared palette's sample always first.
const FIG = 'fig'
type FigEntry = { label: string; path: string }
let figList: FigEntry[] = []
let figView: { kind: 'list' } | { kind: 'image'; entry: FigEntry; src?: string; w?: number; h?: number } = { kind: 'list' }
let figNote = ''
const FIG_MAX = 15

async function loadPicture($: any, path: string): Promise<{ src?: string; w?: number; h?: number; note: string }> {
  try {
    const dims = await $.process.run(['sips', '-g', 'pixelWidth', '-g', 'pixelHeight', path], { timeoutMs: 20000 })
    const w = Number(String(dims.stdout).match(/pixelWidth:\s*(\d+)/)?.[1] ?? 0)
    const h = Number(String(dims.stdout).match(/pixelHeight:\s*(\d+)/)?.[1] ?? 0)
    let src = bytesToBase64(await $.fs.read(path, { as: 'bytes' }))
    if (src.length > MAX_B64) {
      await $.process.run(['sips', '-Z', '1600', path, '--out', THUMB], { timeoutMs: 30000 })
      src = bytesToBase64(await $.fs.read(THUMB, { as: 'bytes' }))
    }
    if (!isBase64(src) || src.length > MAX_B64) return { note: '画像を読めなかった（大きすぎるか、png でない）' }
    return { src, w, h, note: w && h ? `${w} × ${h} px` : '' }
  } catch (err) {
    return { note: `画像を読めなかった（${String(err).slice(0, 60)}）` }
  }
}

async function figLoad($: any, repo: string): Promise<void> {
  const home = String((await $.env.get('HOME')) ?? '')
  const dir = `${home}/.local/share/life/preview`
  const out: FigEntry[] = []
  if (repo) out.push({ label: '共通 12 色の見本（figstyle.GLOBAL）', path: `${repo}/assets/figstyle/palette.png` })
  try {
    const r = await $.process.run(['/bin/sh', '-c', 'ls -t "$1"/*.png 2>/dev/null | head -n "$2"; exit 0', 'sh', dir, String(FIG_MAX)], { timeoutMs: 10000 })
    for (const line of String(r.stdout ?? '').split('\n').map((l: string) => l.trim()).filter(Boolean)) {
      out.push({ label: line.slice(dir.length + 1), path: line })
    }
    figNote = out.length > 1 ? '' : `仮の図はまだありません（${dir}/ に png を置く。figstyle.preview(fig, "名前")）`
  } catch (err) {
    figNote = `仮の図の場所を読めない（${String(err).slice(0, 60)}）`
  }
  figList = out
}

async function figOpen($: any, entry: FigEntry): Promise<void> {
  figView = { kind: 'image', entry }
  figNote = '読み込んでいます…'
  $.ui.invalidate('ui.render')
  const p = await loadPicture($, entry.path)
  figView = { kind: 'image', entry, src: p.src, w: p.w, h: p.h }
  figNote = p.note
  $.ui.invalidate('ui.render')
}

function notesBack($: any): void {
  const v = notesView
  if (v.kind === 'image') notesView = { kind: 'pngs', pj: v.pj, rows: v.rows, row: v.row, files: v.files, deep: true, body: v.body }
  else if (v.kind === 'pngs') notesView = { kind: 'toc', pj: v.pj, rows: v.rows }
  else notesView = { kind: 'list' }
  notesNote = ''
  $.ui.invalidate('ui.render')
}

export function hubLine(h: Hub, width: number): string {
  const age = h.daysSinceUpdate === undefined ? '—' : h.daysSinceUpdate === 0 ? '今日' : `${h.daysSinceUpdate}日前`
  const ms = h.next ? `★${h.next.date} ${h.next.daysLeft}日` : '—'
  const next = h.openNext > 0 ? `次${h.openNext}` : ''
  const head = `${pad(h.slug.split('_').slice(0, 2).join('_').replace(/-.*/, ''), 6)} ${pad(h.status, 8)} ${pad(age, 7)} ${pad(ms, 13)} ${pad(next, 4)} `
  return clip(head + h.title.replace(/\s*\([^)]*\)\s*$/, ''), width)
}

// ---- threads: peers' replies to ops, by sender (threads.ts) ----------------

const THREADS = 'threads'

// LIFE_THREADS_DIR moves the files for a trial run; the real place is outside the repo.
async function threadsDir($: any): Promise<string> {
  const set = await $.env.get('LIFE_THREADS_DIR')
  if (set) return String(set)
  return `${String((await $.env.get('HOME')) ?? '')}/.local/share/life/threads`
}

async function threadRows($: any, path: string): Promise<ThreadRow[]> {
  try {
    return parseRows(String(await $.fs.read(path)))
  } catch {
    return []
  }
}

// One write at a time: two replies landing together must not take one number.
let threadWrites: Promise<unknown> = Promise.resolve()
function serially<T>(work: () => Promise<T>): Promise<T> {
  const run = threadWrites.then(work, work)
  threadWrites = run.catch(() => undefined)
  return run
}

async function threadAppend($: any, name: string, row: Omit<ThreadRow, 'n'>, numberIt: boolean): Promise<number | undefined> {
  const path = fileOf(await threadsDir($), name)
  return serially(async () => {
    const rows = await threadRows($, path)
    const n = numberIt ? nextNumber(rows) : undefined
    await $.fs.write(path, rowsText([...rows, n === undefined ? row : { ...row, n }]))
    return n
  })
}

// Replies read in the running turn, waiting for what ops says of them.
let threadPending: { name: string; n: number; seen?: boolean }[] = []
function blockText(content: unknown): string {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  return content.map((b: any) => (typeof b?.text === 'string' ? b.text : typeof b?.content === 'string' ? b.content : '')).join('\n')
}

// Who sits at which socket, as replies said: a send to a `uds:` address is filed under the name.
const threadSocks = new Map<string, string>()

// The tab: every peer's file, read again only when it changed.
type ThreadFile = { name: string; rows: ThreadRow[] }
const threadCache = new Map<string, { stamp: string; rows: ThreadRow[] }>()

async function loadThreads($: any): Promise<ThreadFile[]> {
  const dir = await threadsDir($)
  let entries: any[] = []
  try {
    entries = await $.fs.list(dir)
  } catch {
    return []
  }
  const out: ThreadFile[] = []
  for (const f of entries) {
    const name = String(f.name)
    if (f.kind !== 'file' || !name.endsWith('.jsonl')) continue
    const path = `${dir}/${name}`
    const stamp = `${f.mtimeMs}:${f.size}`
    let c = threadCache.get(path)
    if (!c || c.stamp !== stamp) {
      c = { stamp, rows: await threadRows($, path) }
      threadCache.set(path, c)
    }
    out.push({ name: name.replace(/\.jsonl$/, ''), rows: c.rows })
  }
  return out
}

async function threadMarkRead($: any, name: string): Promise<void> {
  const path = fileOf(await threadsDir($), name)
  try {
    await serially(async () => {
      const rows = await threadRows($, path)
      if (unread(rows) === 0) return
      await $.fs.write(path, rowsText(rows.map(r => (r.dir === 'in' ? { ...r, read: true } : r))))
    })
    thrNote = ''
  } catch (err) {
    thrNote = `既読にできなかった（${String(err).slice(0, 60)}）`
  }
  $.ui.invalidate('ui.render')
}

// The reply goes to ops, not to the peer (user 10/19): ops reads it and tells the peer.
async function threadsReply($: any, name: string, row: ThreadRow | undefined, text: string): Promise<void> {
  if (!text.trim()) {
    thrNote = '空なので送りませんでした'
  } else {
    try {
      const r = await $.prompt.submit({ text: replyPrompt(name, row, text), asUser: true })
      if (r?.drop !== undefined) thrNote = `ops に送れなかった（${String(r.drop).slice(0, 60)}）`
      else {
        thrNote = `ops に送りました（ops が ${name} に伝えます）`
        thrWriting = false
      }
    } catch (err) {
      thrNote = `ops に送れなかった（${String(err).slice(0, 60)}）`
    }
  }
  $.ui.invalidate('ui.render')
}

let thrPeer: string | undefined // the peer whose thread is shown
let thrAt: number | undefined // the reply n / p moved to
const thrOpen = new Set<string>() // rows shown whole
let thrWriting = false
let thrNote = ''
let thrMore = 0 // older rows shown above the newest THREAD_ROWS
const THREAD_ROWS = 12
const THREAD_FOLD = 4

// today "23:31", another day "10/17"
export function threadWhen(now: number, ms: number): string {
  return dayStart(ms) === dayStart(now) ? hhmm(ms) : `${new Date(ms).getMonth() + 1}/${new Date(ms).getDate()}`
}

// Who this session is, read once per load. Every hook asks, so a skipped
// session.start (or a reload) never leaves the session silent.
let self: Me | undefined
let resolved = false

async function who($: any): Promise<Me | undefined> {
  if (!resolved) {
    self = await whoAmI($)
    resolved = true
  }
  return self
}

export const register: Register = (on, options) => {
  resolved = false
  const python = String(options.python ?? '')
  const repo = String(options.life_repo ?? '')
  slackMcp = parseSlackMcp(String(options.slack_mcp ?? ''))

  on('session.start', async ($, e, next) => {
    const me = await who($)
    if (me) {
      await write($, me, { busy: false })
      if (me.role === 'ops') {
        // The pane shows context and plan usage; no status line (and clear one
        // an earlier version of this mod left).
        $.ui.status(undefined)
        try {
          await $.command.register({ name: 'notes', description: 'Open the research notes: a project, its note contents by number, the pictures under that number, one picture' })
          await $.command.register({ name: 'fig', description: 'Show draft figures any session drops in ~/.local/share/life/preview/ (newest first), and the shared palette' })
          await $.command.register({ name: 'hubs', description: 'Open the project hubs: a list, then one hub by section, with links to related hubs' })
          await $.command.register({ name: 'alert', description: 'Open the alerts: new Gmail (headers only) to mark Done, ask about, or put on the calendar; Slack later' })
          await $.command.register({ name: THREADS, description: 'Open the threads: peers\' replies to ops by sender, numbered, with what ops sent and made of them; a reply typed here goes to ops' })
          await $.command.register({ name: COMMAND, description: 'Open the ops dashboard: every session with a role (busy or idle, context, last turn, last report, last dispatch) and the plan usage' })
          $.clock.every(30000, () => $.ui.invalidate('ui.render'))
          // No toasts (user 10/12): the band shows the counts and the next event.
          void fetchMail($, python, repo)
          $.clock.every(300000, () => fetchMail($, python, repo))
          void fetchSlack($, python, repo)
          $.clock.every(300000, () => fetchSlack($, python, repo))
          void fetchCalendar($, python, repo).then(() => $.ui.invalidate('ui.render'))
          // Open the four panes at start (dash, hubs, notes, threads; user 10/19), without taking the keyboard. Opened
          // unasked, a pane is drawn from 144 columns (110 once the person has
          // opened it); narrower, it waits until the terminal widens or its
          // command is run. dash first: the pane opened first is the one in front
          // (10/08, seen on the terminal: hubs opened first stayed in front), and
          // its tab comes first. notes reads only the hubs here, nothing on the NAS.
          void loadHubs($, repo)
            .then(() => $.ui.open({ id: PANE, title: 'ops-dash', columns: PANE_COLUMNS }))
            .then(() => $.ui.open({ id: HUBS, title: 'hubs', columns: PANE_COLUMNS }))
            .then(() => notesLoad($, repo))
            .then(() => $.ui.open({ id: NOTES, title: 'notes', columns: PANE_COLUMNS }))
            .then(() => $.ui.open({ id: THREADS, title: 'threads', columns: PANE_COLUMNS }))
            // Which tab ends up in front is not the order of opening on every
            // terminal (10/08: with three, notes was in front). Only a focused
            // open raises a tab, so dash is opened again with focus when another
            // is in front; Esc hands the keyboard back to the prompt.
            .then(() => $.ui.panes())
            .then((panes: readonly { id: string; isShown: boolean }[]) =>
              panes.some(p => p.id === PANE && p.isShown) ? undefined : $.ui.open({ id: PANE, title: 'ops-dash', columns: PANE_COLUMNS, focus: true }))
            .catch((err: unknown) => $.ui.log(`ops-dash: could not open the panes at start: ${String(err)}`, { to: 'debug' }))
          $.clock.every(600000, () => fetchCalendar($, python, repo).then(() => $.ui.invalidate('ui.render')))
        } catch (err) {
          $.ui.log(`ops-dash: could not register /${COMMAND}: ${String(err)}`)
        }
      }
    }
    return next(e)
  })

  // Every question put to the person in this session passes here as a
  // tool.call of AskUserQuestion, a guard's $.ui.ask included. While it is
  // open the session is waiting for the person, not working.
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const me = await who($)
    if (!me) return next(e)
    const q = String(e.questions?.[0]?.question ?? '').replace(/\s+/g, ' ').trim()
    await write($, me, { waiting: q.slice(0, 120) || '確認', waitingSince: await $.clock.now() })
    try {
      return await next(e)
    } finally {
      await write($, me, { waiting: undefined, waitingSince: undefined })
    }
  })

  on('turn.start', async ($, e, next) => {
    const me = await who($)
    // No status line: clear any an earlier version of this mod left.
    if (me?.role === 'ops') $.ui.status(undefined)
    if (me) await write($, me, { busy: true, turnStartedAt: await $.clock.now() })
    return next(e)
  })

  // Every session: idle again, and when. ops: what ops told the person in a
  // turn that read peers' replies goes under those replies in their threads.
  // One reply, the whole answer; several, the part under each one's 【b-3】
  // heading (ops-rules asks for them).
  on('turn.complete', async ($, e, next) => {
    const ran = await next(e)
    const me = await who($)
    if (me) await write($, me, { busy: false, lastTurnEndAt: await $.clock.now() })
    if (me?.role !== 'ops' || e.agentId !== undefined || e.reason !== 'answer' || !e.answer.trim() || threadPending.length === 0) return ran
    // Only the replies ops had read before it answered: one landing while the
    // turn ran is often read in the next turn (trial run 10/19, the answers
    // went one reply off). Read: its row entered the conversation
    // (session.append), or the transcript has it before the last answer.
    let messages: { role: string; text: string }[] = []
    try {
      const got = await $.session.messages()
      if (Array.isArray(got)) messages = got
    } catch {
      // the rows seen at session.append decide alone
    }
    const read = threadPending.filter(p => p.seen || readBefore(messages, label(p.name, p.n)))
    threadPending = threadPending.filter(p => !read.includes(p))
    if (read.length === 0) return ran
    try {
      const parts = splitAnswer(e.answer, read.map(r => label(r.name, r.n)))
      const now = await $.clock.now()
      for (const r of read) {
        await threadAppend($, r.name, { dir: 'ops', at: now, ref: r.n, text: parts.get(label(r.name, r.n)) ?? e.answer.trim() }, false)
      }
      $.ui.invalidate('ui.render')
    } catch {
      // ops said it in the conversation anyway; only the copy is lost
    }
    return ran
  })

  on('session.measure', async ($, e, next) => {
    const me = await who($)
    if (me) {
      await write($, me, { contextPercent: e.context.percent, costUsd: e.cost?.usd })
      if (e.rateLimits.length > 0) {
        await $.store.set(LIMITS, {
          at: await $.clock.now(),
          windows: e.rateLimits.map(w => ({ kind: w.kind, percentUsed: w.percentUsed, resetsAt: w.resetsAt })),
        })
      }
      $.ui.invalidate('ui.render')
    }
    return next(e)
  })

  // ops: remember who was sent what. Others: remember when they last reported to ops.
  on('session.send', async ($, e, next) => {
    const ran = await next(e)
    const me = await who($)
    if (me && ran.isDelivered !== false) {
      const now = await $.clock.now()
      if (me.role === 'ops') {
        const line = e.text.split('\n').find(l => l.trim())?.trim().slice(0, 40) ?? ''
        try {
          await $.store.set(DISPATCH + e.to.replace(/ \[[0-9a-f]+\]$/, ''), { at: now, line })
        } catch {
          // a lost dispatch record only blanks one cell
        }
        // The same send in the peer's thread, so request and reply read in one line.
        // A `uds:` address is filed under the name a reply from it gave.
        const to = peerOf(e.to)
        const name = to.startsWith('uds:') ? threadSocks.get(to) : to
        if (e.agentId === undefined && name) {
          try {
            await threadAppend($, name, { dir: 'out', at: now, text: e.text }, false)
            $.ui.invalidate('ui.render')
          } catch {
            // the send went; only its copy in the thread is lost
          }
        }
      } else if (/^ops\b/.test(e.to)) {
        await write($, me, { lastReportAt: now })
      }
    }
    return ran
  })

  // ops: each peer's reply is kept in its thread and numbered; the model still
  // gets the whole of it, the number put at the head of the body. Nothing is
  // taken: a failed record leaves the reply as it came.
  on('session.receive', async ($, e, next) => {
    if (e.origin.kind !== 'peer' || e.agentId !== undefined) return next(e)
    const me = await who($)
    if (me?.role !== 'ops') return next(e)
    const peer = parsePeer(e.text)
    if (!peer) return next(e)
    if (peer.sock) threadSocks.set(peer.sock, peer.name)
    let n: number | undefined
    try {
      n = await threadAppend($, peer.name, { dir: 'in', at: await $.clock.now(), text: peer.body, read: false }, true)
    } catch {
      // the reply goes on unnumbered
    }
    if (n === undefined) return next(e)
    threadPending.push({ name: peer.name, n })
    $.ui.invalidate('ui.render')
    return next({ ...e, text: numbered(e.text, label(peer.name, n)) })
  }).catch(($, e, next) => next(e))

  // A waiting reply is read once its row, number and all, enters ops's conversation.
  on('session.append', async ($, e, next) => {
    // Any row but the model's own (a delivery, a queued prompt's attachment): ops's
    // headings name the numbers too.
    if (threadPending.length > 0 && e.agentId === undefined && e.message.type !== 'assistant' && e.message.role !== 'assistant') {
      const text = blockText(e.message.content)
      for (const p of threadPending) if (text.includes(`【${label(p.name, p.n)}】`)) p.seen = true
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'fig' }, async $ => {
    await figLoad($, repo)
    const newest = figList.find(x => !x.label.startsWith('共通'))
    figView = { kind: 'list' }
    const opened = await $.ui.open({ id: FIG, title: 'fig', columns: PANE_COLUMNS, focus: true })
    if (newest) void figOpen($, newest)
    if (opened.isPlaced) return { text: 'fig opened.' }
    return { text: `fig: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: FIG }, async ($, e) => {
    const { Box, Text, Button, Image } = $.ui.resolve(e)
    const width = Math.max(40, e.props.bodyColumns ?? 84)
    // A reload of this mod empties its memory while the pane stays open:
    // read again here rather than asking for /fig again.
    if (figList.length === 0) await figLoad($, repo)
    const v = figView
    const note = figNote !== '' ? <Text dimColor>{figNote}</Text> : null
    const reload = async () => {
      await figLoad($, repo)
      if (v.kind === 'image') await figOpen($, v.entry)
      else $.ui.invalidate('ui.render')
    }
    if (v.kind === 'list') {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Text bold>fig</Text>
            <Button key="reload" label="更新" hotkey="r" plain onPress={reload} />
          </Box>
          {note}
          <Box flexDirection="column" marginTop={1}>
            {figList.map(f => (
              <Button key={`fig-${f.path}`} label={clip(f.label, width - 2)} plain onPress={() => figOpen($, f)} />
            ))}
          </Box>
        </Box>
      )
    }
    const cols = Math.min(255, Math.max(20, width - 2))
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={2}>
          <Button key="back" label="← 一覧" hotkey="b" plain onPress={() => { figView = { kind: 'list' }; figNote = ''; $.ui.invalidate('ui.render') }} />
          <Text bold>{clip(v.entry.label, width - 24)}</Text>
          <Button key="reload" label="更新" hotkey="r" plain onPress={reload} />
        </Box>
        {note}
        {v.src && <Image key="fig-image" source={{ png: v.src }} columns={cols} rows={imageRows(v.w ?? 0, v.h ?? 0, cols)} alt="（この端末では画像を描けない。CLAUDE_CODE_FORCE_TERMINAL_IMAGES=1 で起動する）" />}
      </Box>
    )
  })

  // A row above the prompt: open dash / hubs / notes without typing a command
  // (a typed /dash stays in the chat). The ops session only; a survey wins.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const me = await who($)
    if (me?.role !== 'ops' || e.props.hasSurvey) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    // Display only (user 10/12): the panes open with /dash /hubs /notes /alert.
    const now = await $.clock.now()
    const gmail = mailFeed ? splitMail(mailFeed.items, mailDone).personal.filter(x => x.unread).length : undefined
    const parts = bandParts(gmail, slackCount(), calendar, now)
    return (
      <Box flexDirection="row" columnGap={2}>
        {parts.map((t, i) => <Text key={`band-${i}`} dimColor={t.endsWith('–') || t === '次の予定なし'}>{t}</Text>)}
      </Box>
    )
  })

  on('command.run', { command: 'alert' }, async $ => {
    void fetchMail($, python, repo)
    const opened = await $.ui.open({ id: ALERT, title: 'alert', columns: PANE_COLUMNS, focus: true })
    if (opened.isPlaced) return { text: 'alert opened.' }
    return { text: `alert: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: ALERT }, async ($, e) => {
    const { Box, Text, Button, Input } = $.ui.resolve(e)
    const nowMs = await $.clock.now()
    const width = Math.max(40, e.props.bodyColumns ?? 84)
    const rule = (label: string) => `─ ${label} ` + '─'.repeat(Math.max(0, width - cells(label) - 3))
    const redraw = () => $.ui.invalidate('ui.render')
    const { personal, bulk } = splitMail(mailFeed?.items ?? [], mailDone)
    const list = [...personal, ...(mailBulkOpen ? bulk : [])]
    const pages = Math.max(1, Math.ceil(list.length / MAIL_ROWS))
    if (mailPage >= pages) mailPage = pages - 1
    const shown = list.slice(mailPage * MAIL_ROWS, (mailPage + 1) * MAIL_ROWS)
    const sel = mailSelected()
    const hasSensitive = sel.some(x => x.sensitive)
    const unread = personal.filter(x => x.unread).length
    const fetched = mailFeed?.fetched_at ? hhmm(Date.parse(mailFeed.fetched_at)) : '—'
    const toggle = (id: string) => {
      if (mailSel.has(id)) mailSel.delete(id)
      else mailSel.add(id)
      redraw()
    }
    const back = () => { mailMode = { kind: 'list' }; redraw() }

    if (chanView) {
      const v = chanView
      const list = v.list ?? []
      const pagesC = Math.max(1, Math.ceil(list.length / CHAN_ROWS))
      const page = Math.min(v.page, pagesC - 1)
      const rows = list.slice(page * CHAN_ROWS, (page + 1) * CHAN_ROWS)
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Button key="chan-back" label="← 戻る" hotkey="b" plain onPress={() => { chanView = undefined; void fetchSlack($, python, repo); redraw() }} />
            <Text bold>{`Slack のチャンネル ${list.length}`}</Text>
          </Box>
          <Text dimColor wrap="wrap">{`印を押すと 見る → メンションだけ → 件数だけ → 見ない と変わる。印の無いものは既定（${WATCH_LABEL[v.def] ?? v.def}）。DM・グループ DM はここに出さない（既定で見る）。戻ると取り直す`}</Text>
          {v.note !== '' && <Text color="red" wrap="wrap">{v.note}</Text>}
          {!v.list && <Text dimColor>読み込んでいます…</Text>}
          {rows.map(c => (
            <Box key={`chan-${c.id}`} flexDirection="row" columnGap={1}>
              <Button key={`chan-w-${c.id}`} label={pad(WATCH_LABEL[c.effective] ?? c.effective, 14)} plain dimColor={!c.watch} onPress={() => chanSet($, python, repo, c.id, nextWatch(c.effective))} />
              <Text wrap="truncate">{clip(`${c.kind === 'private' ? '🔒' : '#'}${c.name}`, Math.max(12, width - 34))}</Text>
              <Text dimColor>{c.workspace}</Text>
            </Box>
          ))}
          {pagesC > 1 && (
            <Box flexDirection="row" columnGap={2}>
              <Button key="chan-prev" label="← 前" hotkey="p" plain dimColor={page === 0} onPress={() => { v.page = Math.max(0, page - 1); redraw() }} />
              <Text dimColor>{`${page + 1}/${pagesC}`}</Text>
              <Button key="chan-next" label="次 →" hotkey="n" plain dimColor={page >= pagesC - 1} onPress={() => { v.page = Math.min(pagesC - 1, page + 1); redraw() }} />
            </Box>
          )}
        </Box>
      )
