          </Box>
          <Box marginTop={1}><Text bold wrap="wrap">{`${it.sensitive ? `［${it.sensitive}］` : ''}${it.subject}`}</Text></Box>
          <Text dimColor wrap="wrap">{`${it.from}  ${shortDate(it.date)}`}</Text>
