        {noteShown('mail', mailNote, mailNoteSeq, nowMs, MAIL_ERR) !== '' && <Text color={MAIL_ERR.test(mailNote) ? 'red' : 'green'} wrap="wrap">{mailNote}</Text>}
        {!mailFeed && mailNote === '' && <Text dimColor>読み込んでいます…（最初の取得は 15 秒ほど）</Text>}
        {shown.map(x => (
