        {mailMode.kind === 'ask' && (
          <Box flexDirection="column" marginTop={1}>
            <Input key="mail-ask-input" label="頼むこと" placeholder="要点と、私がすべきことを短く" submitLabel="下書きに入れる" autoFocus onSubmit={(v: string) => mailAsk($, v)} />
            <Button key="mail-ask-cancel" label="やめる" hotkey="b" plain onPress={back} />
          </Box>
        )}
        {mailMode.kind === 'cal-title' && (
          <Box flexDirection="column" marginTop={1}>
            <Text dimColor>{`予定の題名（${shortDate(mailMode.item.date)} ${mailMode.item.from_name} のメールから）`}</Text>
            <Input key="mail-cal-title" label="題名" value={calendarTitle(mailMode.item)} submitLabel="次へ" autoFocus onSubmit={(v: string) => { const item = (mailMode as { item: MailItem }).item; mailMode = { kind: 'cal-when', item, title: v.trim() || calendarTitle(item) }; redraw() }} />
            <Button key="mail-cal-cancel" label="やめる" hotkey="b" plain onPress={back} />
          </Box>
        )}
        {mailMode.kind === 'cal-when' && (
          <Box flexDirection="column" marginTop={1}>
            <Text dimColor>{`「${mailMode.title}」の日時（30 分の枠で TimeBlock に入れる）`}</Text>
            <Input key="mail-cal-when" label="日時" placeholder="2026-10-15 17:00（日付だけなら 9:00）" submitLabel="カレンダーに入れる" autoFocus onSubmit={(v: string) => mailCalendar($, python, repo, (mailMode as { title: string }).title, v)} />
            <Button key="mail-cal-cancel2" label="やめる" hotkey="b" plain onPress={back} />
          </Box>
        )}

        <Box marginTop={1}><Text dimColor>{rule(`Slack  ${slackFeed ? `${slackCount()} 件（見るチャンネル ${slackFeed.watched}）  取得 ${slackFeed.fetched_at ? hhmm(Date.parse(slackFeed.fetched_at)) : '—'}` : '読み込んでいます…'}`)}</Text></Box>
        {noteShown('slack', slackNote, slackNoteSeq, nowMs, /できなかった|取れなかった/) !== '' && <Text color={/できなかった|取れなかった/.test(slackNote) ? 'red' : 'green'} wrap="wrap">{slackNote}</Text>}
        {slackFeed && slackFeed.watched === 0 && <Text dimColor wrap="wrap">見るチャンネルがまだ無い（~/.config/life/slack-channels.tsv の watch の列に y か count を書く）</Text>}
        {(() => {
          // By conversation (user 10/12: raw rows could not be read), in two
          // parts (user 10/12): DMs and group DMs above, channels below, each
          // with its own pages. The heading says where and how many; the newest
          // three messages go under it, each on its own line.
          const convs = slackConversations(slackFeed?.items ?? [], slackDone, nowMs)
          const selIds = slackSelectedIds(convs, slackSel, slackMsgSel)
          const selCountOnly = convs.some(c => slackSel.has(c.key) && c.countOnly)
          const part = (title: string, list: typeof convs, page: number, setPage: (n: number) => void, keyp: string) => {
            const pages = Math.max(1, Math.ceil(list.length / SLACK_CONVS))
            const p = Math.min(page, pages - 1)
            const shown = list.slice(p * SLACK_CONVS, (p + 1) * SLACK_CONVS)
            const n = list.reduce((k, c) => k + c.ids.length, 0)
            return (
              <Box flexDirection="column" marginTop={1}>
                <Box flexDirection="row" columnGap={2}>
                  <Text bold>{`${title}  ${list.length} 件の会話・${n} 件`}</Text>
                  {pages > 1 && <Button key={`${keyp}-prev`} label="← 前" plain dimColor={p === 0} onPress={() => { setPage(Math.max(0, p - 1)); redraw() }} />}
                  {pages > 1 && <Text dimColor>{`${p + 1}/${pages}`}</Text>}
                  {pages > 1 && <Button key={`${keyp}-next`} label="次 →" plain dimColor={p >= pages - 1} onPress={() => { setPage(Math.min(pages - 1, p + 1)); redraw() }} />}
                </Box>
                {list.length === 0 && <Text dimColor>    新しいものは無い</Text>}
                {shown.map(c => (
                  <Box key={`slk-${c.key}`} flexDirection="column">
                    <Box flexDirection="row" columnGap={1}>
                      <Button key={`slack-sel-${c.key}`} label={slackSel.has(c.key) ? '☑' : '☐'} plain onPress={() => { if (slackSel.has(c.key)) slackSel.delete(c.key); else slackSel.add(c.key); redraw() }} />
                      <Text bold={!c.countOnly} dimColor={c.countOnly} wrap="truncate">{clip(c.place, Math.max(10, width - 34))}</Text>
                      <Text dimColor>{`${c.workspace} · ${c.ids.length} 件${c.countOnly ? '（件数だけ）' : ''}${c.mention ? '（メンション）' : ''}`}</Text>
                    </Box>
                    {c.msgs.slice(0, SLACK_MSGS).map((m, i) => (
                      <Box key={`slkm-${c.key}-${i}`} flexDirection="row" columnGap={1}>
                        <Text>  </Text>
                        <Button key={`slack-msg-${m.id}`} label={slackSel.has(c.key) || slackMsgSel.has(m.id) ? '☑' : '☐'} plain dimColor={slackSel.has(c.key)} onPress={() => { if (slackMsgSel.has(m.id)) slackMsgSel.delete(m.id); else slackMsgSel.add(m.id); redraw() }} />
                        <Text wrap="truncate">{clip(`${m.when} ${m.from}: ${m.head}`, width - 8)}</Text>
                      </Box>
                    ))}
                    {c.msgs.length > SLACK_MSGS && <Text dimColor>{`    …ほか ${c.msgs.length - SLACK_MSGS} 件`}</Text>}
                  </Box>
                ))}
              </Box>
            )
          }
          return (
            <Box flexDirection="column">
              {part('DM・グループ DM', convs.filter(c => c.isDm), slackPage, n => { slackPage = n }, 'slack-dm')}
              {part('チャンネル', convs.filter(c => !c.isDm), slackPageCh, n => { slackPageCh = n }, 'slack-ch')}
              <Box flexDirection="row" columnGap={2} marginTop={1}>
                {selIds.length > 0 && <Button key="slack-done" label={`済みにする（${selIds.length} 件）`} hotkey="z" onPress={() => slackMarkDone($, python, repo, selIds)} />}
                {selIds.length > 0 && !selCountOnly && slackMode === 'list' && <Button key="slack-ask" label="詳しく（モデルに頼む）" hotkey="k" plain onPress={() => { slackMode = 'ask'; redraw() }} />}
                <Button key="slack-reload" label={slackBusy ? '取得中…' : 'Slack を更新'} plain onPress={() => fetchSlack($, python, repo)} />
                <Button key="slack-channels" label="チャンネルを選ぶ" hotkey="w" plain onPress={() => { chanView = { page: 0, def: 'mention', note: '' }; void chanLoad($, python, repo); redraw() }} />
              </Box>
              {selIds.length > 0 && selCountOnly && <Text dimColor>件数だけのチャンネルを含むので「詳しく」は出しません（済みはモデルを通さずにできます）</Text>}
              {slackMode === 'ask' && selIds.length > 0 && (
                <Box flexDirection="row" columnGap={2}>
                  <Input key="slack-ask-input" label="頼むこと" placeholder="要点と、私がすべきことを短く" submitLabel="下書きに入れる" autoFocus onSubmit={(v: string) => slackAsk($, selIds, v)} />
                  <Button key="slack-ask-cancel" label="やめる" plain onPress={() => { slackMode = 'list'; redraw() }} />
                </Box>
              )}
            </Box>
          )
        })()}
      </Box>
    )
  })

  on('command.run', { command: 'threads' }, async $ => {
    thrWriting = false
    const opened = await $.ui.open({ id: THREADS, title: 'threads', columns: PANE_COLUMNS, focus: true })
    if (opened.isPlaced) return { text: 'threads opened.' }
    return { text: `threads: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: THREADS }, async ($, e) => {
    const { Box, Text, Button, Input } = $.ui.resolve(e)
    const width = Math.max(40, e.props.bodyColumns ?? 84)
    const now = await $.clock.now()
    const redraw = () => $.ui.invalidate('ui.render')
    const rule = (text: string) => (text ? `─ ${text} ` + '─'.repeat(Math.max(0, width - cells(text) - 3)) : '─'.repeat(width))
    const files = await loadThreads($)
    const { records } = await readAll($)
    const latest = (f: ThreadFile) => f.rows.reduce((m, r) => Math.max(m, r.at), 0)
    const peers = [...files].sort((a, b) => latest(b) - latest(a))
    if (!thrPeer || !peers.some(p => p.name === thrPeer)) thrPeer = peers[0]?.name
    const total = peers.reduce((k, p) => k + unread(p.rows), 0)
    const cur = peers.find(p => p.name === thrPeer)
    const ordered = cur ? threadOrder(cur.rows) : []
    const replies = ordered.filter(r => r.dir === 'in')
    const rowKey = (r: ThreadRow) => `thr-${r.dir}-${cur?.name}-${r.dir === 'in' ? r.n : `${r.at}-${r.ref ?? ''}`}`
    const focusKey = async (key: string) => {
      try {
        await $.ui.focus({ requestId: THREADS, key })
      } catch {
        // the ring stays where it was
      }
    }

    // the peers: unread, state (the sessions record dash reads), last time, last line
    const nameW = Math.max(10, ...peers.map(p => cells(p.name) + 1))
    const stateOf = (name: string) => {
      const r = records.find(x => x.name === name)
      return !r ? '—' : r.waiting ? '確認待ち' : r.busy ? '作業中' : '待機'
    }
    const peerLine = (p: ThreadFile) => {
      const last = [...p.rows].sort((a, b) => b.at - a.at)[0]
      // the line is the newest reply's first; the time, the thread's newest row
      const said = [...p.rows].filter(r => r.dir === 'in').sort((a, b) => b.at - a.at)[0] ?? last
      const n = unread(p.rows)
      const head = `${p.name === thrPeer ? '●' : ' '} ${pad(p.name, nameW)} ${pad(stateOf(p.name), 9)} ${pad(n ? `${n} 未読` : '', 8)} ${pad(last ? threadWhen(now, last.at) : '', 6)}`
      const line = (said?.text ?? '').split('\n').find(l => l.trim())?.trim() ?? ''
      return clip(`${head}${line}`, width - 2)
    }
    const pick = (name: string) => { thrPeer = name; thrAt = undefined; thrMore = 0; thrNote = ''; redraw() }
    const step = (d: number) => {
      if (peers.length === 0) return
      const i = Math.max(0, peers.findIndex(p => p.name === thrPeer))
      const next = peers[(i + d + peers.length) % peers.length]
      pick(next.name)
      void focusKey(`thr-peer-${next.name}`)
    }
    const move = (d: number) => {
      if (replies.length === 0) return
      const i = replies.findIndex(r => r.n === thrAt)
      const j = i < 0 ? replies.length - 1 : Math.max(0, Math.min(replies.length - 1, i + d))
      const r = replies[j]
      thrAt = r.n
      const back = ordered.length - ordered.indexOf(r)
      if (back > THREAD_ROWS + thrMore) thrMore = back - THREAD_ROWS
      redraw()
      void focusKey(rowKey(r))
    }

    // the thread: newest at the bottom, a long one folded to 4 lines (Enter opens it)
    const shown = ordered.slice(-(THREAD_ROWS + thrMore))
    const heads = shown.map(r =>
      r.dir === 'in' ? `${r.n === thrAt ? '▶' : ' '} ${label(cur!.name, r.n ?? 0)} ${threadWhen(now, r.at)}`
        : r.dir === 'out' ? `  → ops ${threadWhen(now, r.at)}`
          : `    ops ${threadWhen(now, r.at)}`)
    const headW = Math.max(14, ...heads.map(h => cells(h) + 1))
    const bodyW = Math.max(20, width - headW - 2)
    const target = replies.find(r => r.n === thrAt) ?? replies[replies.length - 1]

    return (
      <Box flexDirection="column">
        <Box flexDirection="row">
          <Text bold>{pad('threads', width - 8)}</Text>
          <Text color={total ? 'yellow' : undefined} dimColor={!total}>{`未読 ${total}`}</Text>
        </Box>
        <Text dimColor>{rule('相手')}</Text>
        {peers.length === 0 && <Text dimColor wrap="wrap">まだ返事は届いていません（peer の返事が ops に届くと、ここに相手ごとに並びます）</Text>}
        {peers.map(p => (
          <Button key={`thr-peer-${p.name}`} label={peerLine(p)} plain dimColor={p.name !== thrPeer && unread(p.rows) === 0} onPress={() => pick(p.name)} />
        ))}
        {cur && <Box marginTop={1}><Text dimColor>{rule(cur.name)}</Text></Box>}
        {cur && ordered.length > shown.length && (
          <Button key="thr-older" label={`↑ 前の ${ordered.length - shown.length} 件`} plain dimColor onPress={() => { thrMore += THREAD_ROWS; redraw() }} />
        )}
        {cur && shown.map((r, i) => {
          const key = rowKey(r)
          const lines = wrapCells(r.text, bodyW)
          const open = thrOpen.has(key)
          const body = open ? lines : lines.slice(0, THREAD_FOLD)
          return (
            <Box key={`${key}-box`} flexDirection="row">
              <Button key={key} label={pad(heads[i], headW)} plain dimColor={r.dir === 'out'} onPress={() => { if (thrOpen.has(key)) thrOpen.delete(key); else thrOpen.add(key); if (r.dir === 'in') thrAt = r.n; redraw() }} />
              <Box flexDirection="column">
                {body.map(l => <Text color={r.dir === 'ops' ? 'cyan' : undefined} dimColor={r.dir === 'out'} bold={r.dir === 'in' && !r.read}>{l === '' ? ' ' : l}</Text>)}
                {!open && lines.length > THREAD_FOLD && <Text dimColor>{`…あと ${lines.length - THREAD_FOLD} 行（Enter で全文）`}</Text>}
              </Box>
            </Box>
          )
        })}
        <Text dimColor>{rule('')}</Text>
        {thrNote !== '' && <Text color={/できなかった|送れなかった|空なので/.test(thrNote) ? 'red' : 'green'} wrap="wrap">{thrNote}</Text>}
        {cur && thrWriting && (
          <Box flexDirection="column">
            <Text dimColor wrap="truncate">{clip(target ? `${label(cur.name, target.n ?? 0)} への返事（ops に送り、ops が ${cur.name} に伝える）` : `${cur.name} への返事（ops に送り、ops が伝える）`, width)}</Text>
            <Input key="thr-reply" label="返事 >" placeholder="ops に頼むこと・相手に伝えること" submitLabel="送る" autoFocus onSubmit={(v: string) => threadsReply($, cur.name, target, v)} />
            <Button key="thr-cancel" label="やめる" plain onPress={() => { thrWriting = false; redraw() }} />
          </Box>
        )}
        {!thrWriting && (
          <Box flexDirection="row" columnGap={2} flexWrap="wrap">
            <Button key="thr-reply-open" label="返事" hotkey="r" plain dimColor={!cur} onPress={() => { if (cur) { thrWriting = true; thrNote = ''; redraw() } }} />
            <Button key="thr-read" label="既読" hotkey="a" plain dimColor={!cur || unread(cur.rows) === 0} onPress={() => (cur ? threadMarkRead($, cur.name) : undefined)} />
            <Button key="thr-next-peer" label="次の相手" hotkey="j" plain onPress={() => step(1)} />
            <Button key="thr-prev-peer" label="前の相手" hotkey="k" plain onPress={() => step(-1)} />
            <Button key="thr-next" label="次の返事" hotkey="n" plain onPress={() => move(1)} />
            <Button key="thr-prev" label="前の返事" hotkey="p" plain onPress={() => move(-1)} />
            <Button key="thr-back" label="一覧へ" hotkey="b" plain onPress={() => { thrAt = undefined; thrOpen.clear(); thrMore = 0; redraw(); if (thrPeer) void focusKey(`thr-peer-${thrPeer}`) }} />
          </Box>
        )}
      </Box>
    )
  })

  on('command.run', { command: 'notes' }, async $ => {
    notesView = { kind: 'list' }
    notesNote = ''
    void notesLoad($, repo).then(() => $.ui.invalidate('ui.render'))
    const opened = await $.ui.open({ id: NOTES, title: 'notes', columns: PANE_COLUMNS, focus: true })
    if (opened.isPlaced) return { text: 'notes opened.' }
    return { text: `notes: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: NOTES }, async ($, e) => {
    const { Box, Text, Button, Image, Markdown } = $.ui.resolve(e)
    const width = Math.max(40, e.props.bodyColumns ?? 84)
    // A reload of this mod empties its memory while the pane stays open:
    // read again here rather than asking for /notes again.
    if (notePjs.length === 0) await notesLoad($, repo)
    const v = notesView
    const back = <Button key="back" label="← 戻る" hotkey="b" plain onPress={() => notesBack($)} />
    const note = notesNote !== '' ? <Text dimColor>{notesNote}</Text> : null

    if (v.kind === 'list') {
      return (
        <Box flexDirection="column">
          <Text bold>notes</Text>
          <Text dimColor>hub に nas_code / nas_data がある PJ（目次は選んでから読む）</Text>
          {notePjs.length === 0 && <Text dimColor>見つかりません</Text>}
          {notePjs.map(pj => (
            <Button key={`pj-${pj.slug}`} label={clip(`${pj.slug.split('_').slice(0, 2).join('_')}  ${pj.title}`, width - 2)} plain onPress={() => notesOpenToc($, pj)} />
          ))}
          {note}
        </Box>
      )
    }

    if (v.kind === 'toc') {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>{back}<Text bold>{clip(`${v.pj.slug}  目次 ${v.rows.length} 件`, width - 12)}</Text></Box>
          {note}
          <Box flexDirection="column" marginTop={1}>
            {v.rows.map(r => (
              <Button key={`toc-${r.id}`} label={clip(`${r.id.replace(/^KM_/, '')}  ${r.date === '日付未記載' ? '     ' : r.date.slice(5).replace('-', '/')}  ${r.title}`, width - 2)} plain onPress={() => notesOpenPngs($, v.pj, v.rows, r)} />
            ))}
          </Box>
        </Box>
      )
    }

    if (v.kind === 'pngs') {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>{back}<Text bold>{clip(`${v.row.id}  ${v.row.title}`, width - 12)}</Text></Box>
          <Text dimColor wrap="wrap">{`結論: ${v.row.conclusion}  ／  状態: ${v.row.state}`}</Text>
          {note}
          <Box marginTop={1}><Text dimColor>{clip('─ 本文 ' + '─'.repeat(width), width)}</Text></Box>
          {v.body === undefined && <Text dimColor>本文を読んでいます…</Text>}
          {v.body !== undefined && v.body.length === 0 && <Text dimColor>この番号の見出し（## {v.row.id} — …）が note に無い。ほかの番号の項目に含まれているかもしれない</Text>}
          {v.body !== undefined && v.body.length > 0 && (
            <Markdown key="entry" text={(v.full ? v.body : v.body.slice(0, BODY_LINES)).join('\n')} />
          )}
          {v.body !== undefined && v.body.length > BODY_LINES && (
            <Button key="full" label={v.full ? '本文をたたむ' : `本文の全文（あと ${v.body.length - BODY_LINES} 行）`} hotkey="f" plain onPress={() => { notesView = { ...v, full: !v.full }; $.ui.invalidate('ui.render') }} />
          )}
          <Box marginTop={1}><Text dimColor>{clip('─ out/ の png ' + '─'.repeat(width), width)}</Text></Box>
          {!v.deep && <Button key="deep" label="下の階層も探す（遅い）" hotkey="d" plain onPress={() => notesOpenPngs($, v.pj, v.rows, v.row, true, v.body)} />}
          <Box flexDirection="column" marginTop={1}>
            {v.files.map(f => (
              <Button key={`png-${f}`} label={clip(f, width - 2)} plain onPress={() => notesOpenImage($, v, f)} />
            ))}
          </Box>
        </Box>
      )
    }

    const cols = Math.min(255, Math.max(20, width - 2))
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={2}>{back}<Text bold>{clip(`${v.row.id}  ${v.file}`, width - 12)}</Text></Box>
        {note}
        {v.src && <Image key="note-image" source={{ png: v.src }} columns={cols} rows={imageRows(v.w ?? 0, v.h ?? 0, cols)} alt="（この端末では画像を描けない。CLAUDE_CODE_FORCE_TERMINAL_IMAGES=1 で起動する）" />}
      </Box>
    )
  })

  on('command.run', { command: 'hubs' }, async $ => {
    await loadHubs($, repo)
    view = { kind: 'list' }
    back = []
    const opened = await $.ui.open({ id: HUBS, title: 'hubs', columns: PANE_COLUMNS, focus: true })
    if (opened.isPlaced) return { text: 'hubs opened.' }
    return { text: `hubs: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: HUBS }, async ($, e) => {
    const { Box, Text, Button, Markdown } = $.ui.resolve(e)
    const width = Math.max(40, e.props.bodyColumns ?? 84)
    const redraw = () => $.ui.invalidate('ui.render')
    // A reload of this mod empties its memory while the pane stays open.
    if (hubs.length === 0) await loadHubs($, repo)
    const reload = async () => {
      await loadHubs($, repo)
      redraw()
    }

    if (view.kind === 'list') {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Text bold>{`hubs  ${hubs.length} 件`}</Text>
            <Button key="reload" label="更新" hotkey="r" plain onPress={reload} />
          </Box>
          {hubsNote !== '' && <Text dimColor>{hubsNote}</Text>}
          <Text dimColor>{clip('slug   status   更新    次の Milestone 次の手順', width)}</Text>
          {hubs.map(one => (
            <Button key={`hub-${one.slug}`} label={hubLine(one, width - 2)} plain onPress={() => { openHub(one.slug); redraw() }} />
          ))}
        </Box>
      )
    }

    const hub = hubs.find(x => x.slug === view.slug)
    if (!hub) {
      view = { kind: 'list' }
      return <Text dimColor>その hub が見つかりません。</Text>
    }
    const current = view.tab
    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={2}>
          <Button key="back" label={back.length > 0 ? '← 戻る' : '← 一覧'} hotkey="b" plain onPress={() => { goBack(); redraw() }} />
          <Text bold>{clip(`${hub.slug}  ${hub.title}`, width - 24)}</Text>
          <Button key="reload" label="更新" hotkey="r" plain onPress={reload} />
          <Button key="consult" label="次の一手を相談" hotkey="n" plain onPress={async () => {
            const r = await $.prompt.fill({ text: consultText(hub, `${repo}/projects/active/${hub.slug}.md`) })
            consultNote = r.isFilled ? 'プロンプトに下書きを入れた（直して送る）' : `プロンプトに入れられなかった（${r.reason ?? '理由不明'}）`
            redraw()
          }} />
        </Box>
        {consultNote !== '' && <Text color="green">{consultNote}</Text>}
        <Text dimColor>{clip(`${hub.status} · 更新 ${hub.updated}${hub.next ? ` · ★${hub.next.date} ${hub.next.label} まで ${hub.next.daysLeft}日` : ''}`, width)}</Text>
        <Box flexDirection="row" columnGap={2} marginTop={1}>
          {TABS.map((t, i) => (
            <Button key={`tab-${t.key}`} label={t.label} hotkey={t.key} plain dimColor={i !== current} onPress={() => { view = { kind: 'hub', slug: hub.slug, tab: i }; redraw() }} />
          ))}
        </Box>
        {hub.related.length > 0 && (
          <Box flexDirection="row" columnGap={2}>
            <Text dimColor>関連</Text>
            {hub.related.map(r => {
              const target = hubs.find(x => x.slug === r)
              return target
                ? <Button key={`rel-${r}`} label={`${r.split('_').slice(0, 2).join('_').replace(/-.*/, '')} ↗`} plain onPress={() => { openHub(r); redraw() }} />
                : <Text dimColor>{r}</Text>
            })}
          </Box>
        )}
        <Box marginTop={1}>
          <Markdown key="body" text={sectionMarkdown(hub, current)} />
        </Box>
      </Box>
    )
  })

  on('command.run', { command: COMMAND }, async $ => {
    const opened = await $.ui.open({ id: PANE, title: 'ops-dash', columns: PANE_COLUMNS, focus: true })
    if (opened.isPlaced) return { text: 'ops-dash opened.' }
    return { text: `ops-dash: the pane is waiting and not drawn yet (${opened.reason ?? 'no reason given'}).` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const { records, limits } = await readAll($)
    const now = await $.clock.now()
    const width = Math.max(40, e.props.bodyColumns ?? 58)

    const rule = (label: string) => `─ ${label} ` + '─'.repeat(Math.max(0, width - cells(label) - 3))
    await loadTrend($, repo, now)

    if (trendItem) {
      const it = trendItem
      return (
        <Box flexDirection="column">
          <Button key="back" label={trendList ? '← trend の一覧' : '← dash'} hotkey="b" plain onPress={() => { trendItem = undefined; copied = ''; queueNote = ''; $.ui.invalidate('ui.render') }} />
          <Box marginTop={1}><Text bold wrap="wrap">{it.ja || it.title}</Text></Box>
          <Text wrap="wrap">{it.title}</Text>
          <Box flexDirection="row" columnGap={2} marginTop={1}>
            <Text color="yellow">{starText(it.stars)}</Text>
            <Text dimColor>{it.source}</Text>
            {it.category !== '' && <Text dimColor>{it.category}</Text>}
          </Box>
          <Text color="cyan" wrap="wrap">{it.url}</Text>
          <Box flexDirection="row" columnGap={2} marginTop={1}>
            <Button key="copy-url" label="URL をコピー" hotkey="c" onPress={(press: any) => copyText($, 'URL ', it.url, press)} />
            {repo !== '' && (queued.has(it.url)
              ? <Text color="green">読みたいリストに入っています</Text>
              : <Button key="want" label="読みたい" hotkey="r" onPress={() => addToQueue($, repo, it, (trendShown ?? trend)?.date ?? '')} />)}
          </Box>
          {copied !== '' && <Text color="green">{copied}</Text>}
          {queueNote !== '' && <Text color={queueNote.startsWith('入れられ') ? 'red' : 'green'}>{queueNote}</Text>}
        </Box>
      )
    }

    if (trendPast) {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Button key="back" label="← trend の一覧" hotkey="b" plain onPress={() => { trendPast = false; $.ui.invalidate('ui.render') }} />
            <Text bold>{`過去の trend  ${trendFiles.length} 日`}</Text>
          </Box>
          <Box flexDirection="column" marginTop={1}>
            {trendFiles.map(f => (
              <Button key={`day-${f}`} label={f.slice(0, 10)} plain onPress={() => openPastTrend($, repo, f)} />
            ))}
          </Box>
        </Box>
      )
    }

    const listTrend = trendShown ?? trend
    if (trendList && listTrend) {
      const min = trendList.minStars
      const shown = listTrend.items.filter(x => x.stars >= min)
      const sources = [...new Set(shown.map(x => x.source))]
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Button key="back" label="← dash" hotkey="b" plain onPress={() => { trendList = undefined; trendShown = undefined; $.ui.invalidate('ui.render') }} />
            <Text bold>{`trend ${listTrend.date}  ${shown.length} / ${listTrend.items.length} 件`}</Text>
            <Button key="filter" label={min > 0 ? 'すべて出す' : '★3 以上だけ'} hotkey="s" plain onPress={() => { trendList = { minStars: min > 0 ? 0 : 3 }; $.ui.invalidate('ui.render') }} />
            <Button key="past" label="過去の trend" hotkey="p" plain onPress={() => { trendPast = true; $.ui.invalidate('ui.render') }} />
          </Box>
          {sources.map(src => (
            <Box flexDirection="column" marginTop={1}>
              <Text dimColor>{rule(src)}</Text>
              {shown.filter(x => x.source === src).map(x => (
                <Button key={`tr-${x.order}`} label={clip(`${queued.has(x.url) ? '📥 ' : ''}${starText(x.stars)} ${x.ja || x.title}`, width - 2)} plain onPress={() => { trendItem = x; copied = ''; queueNote = ''; void refreshQueued($, repo).then(() => $.ui.invalidate('ui.render')); $.ui.invalidate('ui.render') }} />
              ))}
            </Box>
          ))}
        </Box>
      )
    }

    if (taskDetail) {
      const { task: t, section } = taskDetail
      if (hubs.length === 0) await loadHubs($, repo)
      const hubSlug = hubOfTag(t.tag, hubs.map(x => x.slug))
      const left = t.deadline ? daysLeft(now, t.deadline) : undefined
      const leftLabel = left === undefined ? '' : left < 0 ? `（${-left} 日過ぎ）` : left === 0 ? '（今日）' : `（あと ${left} 日）`
      const dueColor = t.done || left === undefined ? undefined : left < 0 ? 'red' : left <= 3 ? 'yellow' : undefined
      const row = (label: string, value: string, color?: string) => (
        <Box flexDirection="row">
          <Text dimColor>{pad(label, 6)}</Text>
          <Text color={color} wrap="wrap">{value}</Text>
        </Box>
      )
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Button key="back" label="← タスクの一覧" hotkey="b" plain onPress={() => closeTask($)} />
          </Box>
          <Box flexDirection="row" marginTop={1}>
            <Text>{t.done ? '✅ ' : '⬜ '}</Text>
            <Text color={tagColor(t.tag)}>{t.tag ? `${t.tag}  ` : ''}</Text>
            <Text dimColor>{section}</Text>
          </Box>
          <Box marginTop={1}><Text bold wrap="wrap">{t.full}</Text></Box>
          <Box flexDirection="column" marginTop={1}>
            {row('担当', t.who || '—')}
            {t.created && row('起票', t.created)}
            {row('締切', t.deadline ? `${t.deadline.month}/${t.deadline.day}${leftLabel}` : '—', dueColor)}
            {t.note && !t.deadline && row('補足', t.note)}
            {t.note && t.deadline && t.note !== `${t.deadline.month}/${t.deadline.day}` && row('補足', t.note)}
          </Box>
          {hubSlug && (
            <Box flexDirection="row" marginTop={1}>
              <Button key="hub" label={`${hubSlug.split('_').slice(0, 2).join('_').replace(/-.*/, '')} の hub ↗`} hotkey="h" plain onPress={() => goToHub($, hubSlug)} />
            </Box>
          )}
        </Box>
      )
    }

    if (detail) {
      const ev = detail
      if (hubs.length === 0) await loadHubs($, repo)
      const hubSlug = hubOfEvent(ev, hubs.map(x => x.slug))
      const desc = (ev.description ?? '').split('\n').map(l => l.trimEnd())
      const DESC_LINES = 12
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={2}>
            <Button key="back" label="← 予定の一覧" hotkey="b" plain onPress={() => closeEvent($)} />
          </Box>
          <Box marginTop={1}><Text bold wrap="wrap">{ev.title}</Text></Box>
          <Text>{whenLabel(ev, now)}</Text>
          {ev.location && <Text wrap="wrap">{`場所  ${ev.location}`}</Text>}
          {ev.meetingUrl && <Text color="cyan" wrap="wrap">{ev.meetingUrl}</Text>}
          <Box flexDirection="row" columnGap={2} marginTop={1} flexWrap="wrap">
            {ev.meetingUrl && <Button key="copy-url" label="会議 URL をコピー" hotkey="c" onPress={(press: any) => copyText($, '会議 URL ', ev.meetingUrl!, press)} />}
            {ev.location && <Button key="copy-loc" label="場所をコピー" hotkey="l" plain onPress={(press: any) => copyText($, '場所', ev.location!, press)} />}
            {ev.htmlLink && <Button key="copy-page" label="予定のページをコピー" hotkey="p" plain onPress={(press: any) => copyText($, '予定のページ', ev.htmlLink!, press)} />}
            {hubSlug && <Button key="hub" label={`${hubSlug.split('_').slice(0, 2).join('_').replace(/-.*/, '')} の hub ↗`} hotkey="h" plain onPress={() => goToHub($, hubSlug)} />}
          </Box>
          {copied !== '' && <Text color="green">{copied}</Text>}
          {desc.some(l => l) && (
            <Box flexDirection="column" marginTop={1}>
              {desc.slice(0, DESC_LINES).map(l => <Text dimColor wrap="wrap">{clip(l, width * 3)}</Text>)}
              {desc.length > DESC_LINES && <Text dimColor>{`…ほか ${desc.length - DESC_LINES} 行`}</Text>}
            </Box>
          )}
        </Box>
      )
    }

    // plan usage: two short lines
    const limitLines = limitRows(limits, now)
    const smallBar = Math.max(6, Math.min(14, width - 34))

    // sessions: one line each
    const sorted = [...records].sort((a, b) => (a.role === 'ops' ? -1 : b.role === 'ops' ? 1 : a.name.localeCompare(b.name)))
    const peerBar = Math.max(6, Math.min(12, width - 40))
    // The name and pj columns take the widest entry, so every bar starts at the same column (user 10/15).
    const nameW = Math.max(10, ...sorted.map(r => cells(r.name) + 1))
    const pjW = Math.max(5, ...sorted.map(r => cells(r.pj ?? '') + 1))

    // calendar: fixed height, then the next few events as buttons
    const next = upcoming(calendar, now, NEXT_EVENTS)
    const dayWidth = Math.max(5, Math.floor((width - 3) / 7))
    const week = weekGrid(calendar, now, dayWidth)

    // tasks: grows; the pane scrolls
    let tasks: TaskSection[] = []
    let taskNote = ''
    if (repo) {
      try {
        tasks = parseTasks(String(await $.fs.read(`${repo}/ideas/task-review/tasks.md`)))
      } catch {
        taskNote = 'tasks.md を読めない'
      }
    } else taskNote = 'タスク未設定（pluginConfigs の life_repo）'

    // Jumps: the first button of each long section (c / r / k; t is the trend list's).
    const trendTop = trend ? topItems(trend.items, TREND_ROWS) : []
    const firstTask = tasks.flatMap(sec => [...sec.tasks.filter(t => !t.done), ...sec.tasks.filter(t => t.done)].map(t => `task-${sec.title}-${t.full}`))[0]
    const jumps: { hotkey: string; label: string; key?: string }[] = [
      { hotkey: 'c', label: 'calendar', key: next[0] ? `ev-0-${next[0].start}` : undefined },
      { hotkey: 'r', label: 'trend', key: trendTop[0] ? `trend-${trendTop[0].order}` : undefined },
      { hotkey: 'k', label: 'tasks', key: firstTask },
    ]
    const jump = async (key?: string) => {
      if (!key) return
      try {
        await $.ui.focus({ requestId: PANE, key })
      } catch {
        // the ring stays where it was
      }
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" columnGap={2}>
          {jumps.map(j => <Button key={`jump-${j.hotkey}`} label={j.label} hotkey={j.hotkey} plain dimColor={!j.key} onPress={() => jump(j.key)} />)}
        </Box>
        <Box marginBottom={1}><Text dimColor>{rule('system usage')}</Text></Box>
        {limitLines.length === 0 && <Text dimColor>まだ計測なし</Text>}
        {limitLines.map(l => (
          <Box flexDirection="row">
            <Text>{pad(l.label, 8)}</Text>
            <Text color={tone(l.percent)}>{bar(l.percent, smallBar)}</Text>
            <Text bold>{` ${String(Math.round(l.percent)).padStart(3)}%`}</Text>
            <Text dimColor>{`  ${l.reset}`}</Text>
          </Box>
        ))}

        <Box marginTop={1} marginBottom={1}><Text dimColor>{rule('sessions')}</Text></Box>
        {sorted.length === 0 && <Text dimColor>まだ状態を書いたセッションなし</Text>}
        {sorted.map(r => (
          <Box flexDirection="row">
            <Text color={r.waiting ? 'red' : r.busy ? 'yellow' : 'green'}>{r.waiting ? '◆ ' : r.busy ? '● ' : '○ '}</Text>
            <Text bold>{pad(r.name, nameW)}</Text>
            <Text dimColor>{pad(r.pj ?? '', pjW)}</Text>
            {r.contextPercent === undefined ? (
              <Text dimColor>{pad('ctx —', peerBar + 5)}</Text>
            ) : (
              <Box flexDirection="row">
                <Text color={tone(r.contextPercent)}>{bar(r.contextPercent, peerBar)}</Text>
                <Text>{` ${String(Math.round(r.contextPercent)).padStart(3)}%`}</Text>
              </Box>
            )}
            {r.waiting ? (
              <Text color="red" bold>{`  確認待ち ${elapsed(now, r.waitingSince)}`}</Text>
            ) : (
              <Text color={r.busy ? 'yellow' : undefined} dimColor={!r.busy}>
                {r.busy ? `  作業中 ${elapsed(now, r.turnStartedAt)}` : r.lastTurnEndAt ? `  ${ago(now, r.lastTurnEndAt)}` : '  —'}
              </Text>
            )}
          </Box>
        ))}

        <Box marginTop={1} marginBottom={1}><Text dimColor>{rule(`calendar  ${calendarNote}`)}</Text></Box>
        <Box flexDirection="row">
          <Text>{'   '}</Text>
          {week.days.map(d => (
            <Text bold={d.isToday} inverse={d.isToday}>{pad(d.label, dayWidth)}</Text>
          ))}
        </Box>
        <Box flexDirection="row">
          <Text dimColor>{'終 '}</Text>
          {week.allDay.map(c => (c.color ? <Text backgroundColor={c.color} color="black">{c.text}</Text> : <Text dimColor>{c.text}</Text>))}
        </Box>
        {week.hours.map(row => (
          <Box flexDirection="row">
            <Text color={row.isNow ? 'yellow' : undefined} dimColor={!row.isNow} bold={row.isNow}>{`${row.label} `}</Text>
            {row.cells.map(c => (c.color ? <Text backgroundColor={c.color} color="black">{c.text}</Text> : <Text dimColor>{c.text.replace(/ (?=$)/, '·').replace(/^ /, ' ')}</Text>))}
          </Box>
        ))}
        <Box flexDirection="column" marginTop={1}>
          {next.length === 0 && <Text dimColor>この先の予定なし</Text>}
          {next.map((ev, i) => (
            <Button
              key={`ev-${i}-${ev.start}`}
              label={clip(`${pad(whenLabel(ev, now), 18)} ${ev.title.replace(/\[status:[^\]]+\]/g, '').trim()}${ev.meetingUrl ? '  🔗' : ''}`, width - 2)}
              plain
              onPress={() => openEvent($, ev)}
            />
          ))}
          {Array.from({ length: NEXT_EVENTS - Math.max(1, next.length) }, () => <Text> </Text>)}
        </Box>

        <Box marginTop={1} marginBottom={1}><Text dimColor>{rule(trend ? `trend ${trend.date.slice(5).replace('-', '/')}（${trend.items.length} 件・★3 以上 ${trend.items.filter(x => x.stars >= 3).length} 件）` : `trend  ${trendNote}`)}</Text></Box>
        {(() => {
          const top = trend ? topItems(trend.items, TREND_ROWS) : []
          return (
            <Box flexDirection="column">
              {top.map(x => (
                <Button key={`trend-${x.order}`} label={clip(`${pad('★'.repeat(x.stars), 6)}${pad(x.short, 5)}${x.ja || x.title}`, width - 2)} plain onPress={() => { trendItem = x; trendList = undefined; trendShown = undefined; copied = ''; queueNote = ''; void refreshQueued($, repo).then(() => $.ui.invalidate('ui.render')); $.ui.invalidate('ui.render') }} />
              ))}
              {Array.from({ length: TREND_ROWS - top.length }, () => <Text> </Text>)}
              {trend && <Button key="trend-all" label="全部を見る（過去の trend も）" hotkey="t" plain onPress={() => { trendList = { minStars: 0 }; trendItem = undefined; trendShown = undefined; void refreshQueued($, repo).then(() => $.ui.invalidate('ui.render')); $.ui.invalidate('ui.render') }} />}
            </Box>
          )
        })()}

        <Box marginTop={1} marginBottom={1}><Text dimColor>{rule('tasks')}</Text></Box>
        {taskNote !== '' && <Text dimColor>{taskNote}</Text>}
        {tasks.map(section => {
          const open = section.tasks.filter(t => !t.done)
          const done = section.tasks.filter(t => t.done)
          const head = `残り ${open.length}`
          return (
            <Box flexDirection="column" marginBottom={1}>
              <Box flexDirection="row">
                <Text bold>{pad(section.title, width - cells(head))}</Text>
                <Text dimColor>{head}</Text>
              </Box>
              {[...open, ...done].map(t => {
                const left = t.deadline ? daysLeft(now, t.deadline) : undefined
                const due = t.deadline ? `〆${t.deadline.month}/${t.deadline.day}` : ''
                const who = t.owner ? `→ ${t.owner}` : ''
                const meta = [who, due].filter(Boolean).join('  ')
                const titleWidth = Math.max(8, width - 3 - 6 - (meta ? cells(meta) + 2 : 0))
                const dueColor = t.done || left === undefined ? undefined : left < 0 ? 'red' : left <= 3 ? 'yellow' : undefined
                return (
                  <Box flexDirection="row">
                    <Text dimColor={t.done}>{t.done ? '✅ ' : '⬜ '}</Text>
                    <Text color={t.done ? undefined : tagColor(t.tag)} dimColor={t.done}>{shortTag(t.tag, 5) + ' '}</Text>
                    <Button key={`task-${section.title}-${t.full}`} label={pad(clip(t.title, titleWidth), titleWidth)} plain dimColor={t.done} onPress={() => openTask($, t, section.title)} />
                    {who !== '' && <Text dimColor>{'  ' + who}</Text>}
                    {due !== '' && <Text color={dueColor} dimColor={dueColor === undefined}>{'  ' + due}</Text>}
                  </Box>
                )
              })}
            </Box>
          )
        })}
      </Box>
    )
  })
}

